practice.solution:
def discounted(rewards, gamma):
    t = 0.0
    g = 1.0
    for r in rewards:
        t += g * r
        g *= gamma
    return round(t, 6)

def upsilon(envs):
    t = 0.0
    for k, v in envs:
        t += v * (0.5 ** k)
    return round(t, 6)

def shared_birthday(n):
    p = 1.0
    for i in range(n):
        p *= (365 - i) / 365.0
    return round(1.0 - p, 4)
